action.command:
powershell -NoProfile -Command "
param($input)
\$json = \$input | ConvertFrom-Json
\$cmd = \$json.toolInput.command

# Comandos de solo lectura (no requieren confirmación)
\$readOnlyPatterns = @(
    'aws\s+\w+\s+describe',
    'aws\s+\w+\s+get',
    'aws\s+\w+\s+list',
    'aws\s+\w+\s+query',
    'aws\s+ec2\s+describe',
    'terraform\s+plan',
    'terraform\s+show',
    'terraform\s+validate'
)

# Comandos de escritura (requieren confirmación)
\$writePatterns = @(
    'aws\s+\w+\s+create',
    'aws\s+\w+\s+put',
    'aws\s+\w+\s+update',
    'aws\s+\w+\s+delete',
    'aws\s+\w+\s+modify',
    'terraform\s+apply',
    'terraform\s+destroy'
)

\$isReadOnly = \$false
\$isWrite = \$false

foreach (\$pattern in \$readOnlyPatterns) {
    if (\$cmd -match \$pattern) {
        \$isReadOnly = \$true
        break
    }
}

foreach (\$pattern in \$writePatterns) {
    if (\$cmd -match \$pattern) {
        \$isWrite = \$true
        break
    }
}

if (\$isWrite -and -not \$isReadOnly) {
    \$output = @{
        hookSpecificOutput = @{
            permissionDecision = 'ask'
            permissionDecisionReason = 'Este es un comando AWS/Terraform de escritura que puede modificar recursos'
        }
    }
    Write-Output (\$output | ConvertTo-Json)
    exit 0
} else {
    exit 0
}
"
